
import { getComponentSettings } from '@/core/settings'
import {
  addNavbarListener,
  getNavbarSession,
  isNavbarActive,
  isNavbarSessionActive,
} from '../lifecycle'
import { getJson } from '@/core/ajax'
import { VIcon } from '@/ui'

export default Vue.extend({
  name: 'NavbarLogo',
  components: {
    VIcon,
  },
  data() {
    return {
      seasonLogoUrl: '',
      useThemeColor: true,
    }
  },
  watch: {
    seasonLogoUrl() {
      document.body.classList.toggle(
        'season-logo-enabled',
        isNavbarActive() && Boolean(this.seasonLogoUrl),
      )
    },
  },
  async created() {
    addNavbarListener(
      'customNavbar.seasonLogo',
      async (value: boolean) => {
        if (!value) {
          this.seasonLogoUrl = ''
          return
        }
        const session = getNavbarSession()
        try {
          const json = await getJson(
            'https://api.bilibili.com/x/web-show/page/header?resource_id=1',
          )
          if (
            !isNavbarSessionActive(session) ||
            !getComponentSettings('customNavbar').options.seasonLogo
          ) {
            return
          }
          this.seasonLogoUrl =
            json.code === 0 ? lodash.get(json, 'data.litpic', '').replace('http:', 'https:') : ''
          document.body.classList.toggle('season-logo-enabled', Boolean(this.seasonLogoUrl))
        } catch {
          if (isNavbarSessionActive(session)) {
            this.seasonLogoUrl = ''
          }
        }
      },
      true,
    )
    addNavbarListener(
      'customNavbar.themeLogo',
      async (value: boolean) => {
        this.useThemeColor = value
      },
      true,
    )
  },
})
