
import { addComponentListener } from '../core/settings'
import { getFriendlyTitle } from '../core/utils/title'
import { getBlob } from '../core/ajax'
import VIcon from './icon/VIcon.vue'

export default Vue.extend({
  components: {
    VIcon,
  },
  data() {
    return {
      image: '',
      filename: '',
      blobFilename: '',
      open: false,
      blobUrl: '',
      keyHandler: null,
      copiedTimer: 0,
    }
  },
  mounted() {
    this.keyHandler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        this.open = false
      }
    }
    document.addEventListener('keydown', this.keyHandler)
    addComponentListener(
      'settingsPanel.filenameFormat',
      () => {
        this.updateFilename()
      },
      true,
    )
  },
  beforeDestroy() {
    document.removeEventListener('keydown', this.keyHandler)
  },
  methods: {
    async copyLink() {
      await navigator.clipboard.writeText(this.image)
      if (this.copiedTimer) {
        window.clearTimeout(this.copiedTimer)
      }
      this.copiedTimer = window.setTimeout(() => {
        this.copiedTimer = 0
      }, 2000)
    },
    newTab() {
      window.open(this.image, '_blank')
    },
    detectOutside(e: MouseEvent) {
      const container = this.$el
      const { viewer } = this.$refs
      if (e.target === container || e.target === viewer) {
        // this.$emit('change', false)
        this.open = false
      }
    },
    updateFilename() {
      const url = this.image as string
      if (!url) {
        this.filename = ''
        return
      }
      this.filename = this.blobFilename
        ? this.blobFilename
        : getFriendlyTitle(document.URL.includes('/www.bilibili.com/bangumi/')) +
          url.substring(url.lastIndexOf('.'))
    },
    async setImage(url: string, blobFilename?: string) {
      if (this.blobUrl) {
        URL.revokeObjectURL(this.blobUrl)
      }
      if (!url) {
        this.blobUrl = ''
        this.image = ''
      }
      this.image = url
      this.blobFilename = ''
      if (url.startsWith('blob:')) {
        this.blobUrl = url
        if (!blobFilename) {
          throw new Error('[ImageViewer] Blob格式图片未指定文件名')
        }
        this.blobFilename = blobFilename
      } else {
        const blob = await getBlob(url)
        this.blobUrl = URL.createObjectURL(blob)
      }
      this.updateFilename()
    },
  },
})
